// Package bpf holds the compiled BPF programs (generated by bpf2go, see go generate).
package bpf

// -isystem makes vmlinux.h (generated, included as <vmlinux.h>) a system header, so the
// extended set and -Werror judge only authored lines; authored headers are included with
// quotes and stay user headers.
//go:generate go tool bpf2go -cc clang -cflags "-O2 -g -Wall -Werror -Wno-missing-declarations -Wextra -Wshadow -Wvla -Wundef -Wpointer-arith -Wimplicit-fallthrough -Wstrict-prototypes -Wnull-dereference -Wconversion" -target amd64 -type event -type rule_key -type exe_key -type control_state -type rule_val -type byte_count Snitch ../../bpf/snitch.bpf.c -- -isystem ../../bpf

// v3 gives 32-bit subregister ops so the verifier tracks the bounded lengths read_qname proves.
// Without it the load is rejected.
//go:generate go tool bpf2go -cc clang -cflags "-O2 -g -Wall -Werror -Wno-missing-declarations -Wextra -Wshadow -Wvla -Wundef -Wpointer-arith -Wimplicit-fallthrough -Wstrict-prototypes -Wnull-dereference -Wconversion -mcpu=v3" -target amd64 -type dns_answer_record -type domain_key -type domain_val -type domain_slot -type resolver_key -type q_key -type q_val Dns ../../bpf/dns.bpf.c -- -isystem ../../bpf
